  2→
  3→import { Badge } from '@tpmjs/ui/Badge/Badge';
  4→import { Button } from '@tpmjs/ui/Button/Button';
  5→import { Icon } from '@tpmjs/ui/Icon/Icon';
  6→import { Textarea } from '@tpmjs/ui/Textarea/Textarea';
  7→import { registerBuiltInRenderers } from '@tpmjs/ui/ToolRenderer/registerBuiltInRenderers';
  8→import { ToolRenderer } from '@tpmjs/ui/ToolRenderer/ToolRenderer';
  9→import type { ToolPart, ToolState } from '@tpmjs/ui/ToolRenderer/types';
 10→import Link from 'next/link';
 11→import { useParams, useRouter } from 'next/navigation';
 12→import { useCallback, useEffect, useRef, useState } from 'react';
 13→import { Streamdown } from 'streamdown';
 14→import { AppHeader } from '~/components/AppHeader';
 15→import { EnvVarWarningBanner } from '~/components/omega/EnvVarWarningBanner';
 16→
 17→// Initialize built-in tool renderers (idempotent)
 18→registerBuiltInRenderers();
 19→
 20→interface ToolDiscoveryInfo {
 21→  staticTools?: string[];
 22→  dynamicToolsLoaded?: string[];
 23→  autoDiscoveredTools?: Array<{
 24→    toolId: string;
 25→    name: string;
 26→    packageName: string;
 27→    description: string;
 28→  }>;
 29→}
 30→
 31→interface Message {
 32→  id: string;
 33→  role: 'USER' | 'ASSISTANT' | 'TOOL';
 34→  content: string;
 35→  toolCalls?: Array<{
 36→    toolCallId: string;
 37→    toolName: string;
 38→    args?: unknown;
 39→    output?: unknown;
 40→  }>;
 41→  inputTokens?: number;
 42→  outputTokens?: number;
 43→  createdAt: string;
 44→  // Tool discovery info (populated from SSE events, per message)
 45→  toolDiscovery?: ToolDiscoveryInfo;
 46→}
 47→
 48→interface ToolCall {
 49→  toolCallId: string;
 50→  toolName: string;
 51→  input?: unknown;
 52→  output?: unknown;
 53→  status: 'pending' | 'running' | 'success' | 'error';
 54→  isError?: boolean;
 55→}
 56→
 57→interface EnvVarWarning {
 58→  toolId: string;
 59→  toolName: string;
 60→  packageName: string;
 61→  envVar: {
 62→    name: string;
 63→    description: string;
 64→    required: boolean;
 65→  };
 66→}
 67→
 68→interface Conversation {
 69→  id: string;
 70→  title: string | null;
 71→  executionState: string;
 72→  inputTokensTotal: number;
 73→  outputTokensTotal: number;
 74→  createdAt: string;
 75→  updatedAt: string;
 76→}
 77→
 78→/**
 79→ * Convert ToolCall status to ToolState
 80→ */
 81→function statusToToolState(status: ToolCall['status']): ToolState {
 82→  switch (status) {
 83→    case 'pending':
 84→      return 'partial-call';
 85→    case 'running':
 86→      return 'call';
 87→    case 'success':
 88→    case 'error':
 89→      return 'result';
 90→  }
 91→}
 92→
 93→/**
 94→ * Convert ToolCall to ToolPart for rendering
 95→ */
 96→function toolCallToToolPart(tc: ToolCall): ToolPart {
 97→  return {
 98→    type: tc.status === 'success' || tc.status === 'error' ? 'tool-result' : 'tool-call',
 99→    toolCallId: tc.toolCallId,
100→    toolName: tc.toolName,
101→    args: tc.input,
102→    result: tc.isError ? { error: tc.output } : tc.output,
103→    state: statusToToolState(tc.status),
104→  };
105→}
106→
107→/**
108→ * Omega Chat Page
109→ */
110→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex chat page with multiple UI states and SSE handling
111→export default function OmegaChatPage(): React.ReactElement {
112→  const params = useParams();
113→  const router = useRouter();
114→  const conversationId = params.conversationId as string;
115→
116→  const [conversation, setConversation] = useState<Conversation | null>(null);
117→  const [messages, setMessages] = useState<Message[]>([]);
118→  const [input, setInput] = useState('');
119→  const [isLoading, setIsLoading] = useState(true);
120→  const [isSending, setIsSending] = useState(false);
121→  const [streamingContent, setStreamingContent] = useState('');
122→  const [error, setError] = useState<string | null>(null);
123→  const [toolCalls, setToolCalls] = useState<ToolCall[]>([]);
124→  const [viewMode, setViewMode] = useState<'chat' | 'debug'>('chat');
125→  // Map of message IDs to their tool discovery info (persisted in frontend state)
126→  const [messageToolDiscovery, setMessageToolDiscovery] = useState<Map<string, ToolDiscoveryInfo>>(
127→    new Map()
128→  );
129→  // Environment variable warnings for tools that need API keys
130→  const [envWarnings, setEnvWarnings] = useState<EnvVarWarning[]>([]);
131→  // Status message from SSE status events
132→  const [statusMessage, setStatusMessage] = useState<string | null>(null);
133→
