    prompt: 'Search for the latest news about AI agents and summarize the key developments',
    icon: 'search',
  },
  {
    title: 'Code Generation',
    description: 'Generate code for various tasks',
    prompt: 'Find a tool that can generate QR codes and create one for https://tpmjs.com',
    icon: 'terminal',
  },
  {
    title: 'Image Processing',
    description: 'Work with images and files',
    prompt: 'Find image processing tools and tell me what they can do',
    icon: 'box',
  },
  {
    title: 'Data Analysis',
    description: 'Analyze and transform data',
    prompt: 'Search for data processing tools that can help me analyze JSON data',
    icon: 'folder',
  },
  {
    title: 'Creative Tasks',
    description: 'Generate content and ideas',
    prompt: 'Find a blog post creation tool and write a short post about the future of AI',
    icon: 'star',
  },
];

/**
 * Omega Landing Page
 * Shows sample prompts and starts new conversations
 */
export default function OmegaLandingPage(): React.ReactElement {
  const router = useRouter();
  const { data: session, isPending: isSessionLoading } = useSession();
  const [isCreating, setIsCreating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isAuthenticated = !!session?.user;

  const createConversation = useCallback(
    async (initialPrompt?: string) => {
      if (!isAuthenticated) {
        // Redirect to sign-in if not authenticated
        const returnUrl = initialPrompt
          ? `/omega?prompt=${encodeURIComponent(initialPrompt)}`
          : '/omega';
        router.push(`/sign-in?returnTo=${encodeURIComponent(returnUrl)}`);
        return;
      }

      setIsCreating(true);
      setError(null);

      try {
        const response = await fetch('/api/omega/conversations', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
        });

        if (!response.ok) {
          const data = await response.json();
          if (response.status === 401) {
            // Session expired, redirect to sign-in
            router.push(`/sign-in?returnTo=${encodeURIComponent('/omega')}`);
            return;
          }
          throw new Error(data.error?.message || data.error || 'Failed to create conversation');
        }

        const data = await response.json();
        const conversationId = data.data.id;

        // Navigate to chat, optionally with initial prompt
        if (initialPrompt) {
          sessionStorage.setItem(`omega_prompt_${conversationId}`, initialPrompt);
        }
        router.push(`/omega/${conversationId}`);
      } catch (err) {
        console.error('Failed to create conversation:', err);
        setError(err instanceof Error ? err.message : 'Failed to create conversation');
        setIsCreating(false);
      }
    },
    [router, isAuthenticated]
  );

  // Handle prompt query parameter (redirect from sign-in)
  useEffect(() => {
    if (isAuthenticated && typeof window !== 'undefined') {
      const params = new URLSearchParams(window.location.search);
      const prompt = params.get('prompt');
      if (prompt) {
        // Clear the query parameter
        window.history.replaceState({}, '', '/omega');
        // Create conversation with the prompt
        createConversation(prompt);
      }
    }
  }, [isAuthenticated, createConversation]);

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <AppHeader />

      <main className="flex-1 flex items-center justify-center p-4">
        <div className="w-full max-w-4xl">
          {/* Hero Section */}
          <div className="text-center mb-12">
            <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-gradient-to-br from-primary/20 to-accent/20 mb-6">
              <Icon icon="star" size="lg" className="text-primary" />
            </div>
            <h1 className="text-4xl md:text-5xl font-bold text-foreground mb-4">Meet Omega</h1>
            <p className="text-lg text-foreground-secondary max-w-2xl mx-auto">
              An AI assistant with access to over 1 million tools. Just describe what you need, and
              Omega will find and use the right tools to help you.
            </p>
          </div>

          {/* Start New Conversation */}
          <div className="flex justify-center mb-12">
            {isSessionLoading ? (
              <Button size="lg" disabled className="px-8">
                <Icon icon="loader" size="sm" className="mr-2 animate-spin" />
                Loading...
              </Button>
            ) : isAuthenticated ? (
              <Button
                size="lg"
                onClick={() => createConversation()}
                disabled={isCreating}
                className="px-8"
              >
                {isCreating ? (
                  <>
                    <Icon icon="loader" size="sm" className="mr-2 animate-spin" />
                    Creating...
                  </>
                ) : (
                  <>
                    <Icon icon="plus" size="sm" className="mr-2" />
                    Start New Conversation
                  </>
                )}
              </Button>
            ) : (
              <div className="flex flex-col items-center gap-4">
                <Link
                  href={`/sign-in?returnTo=${encodeURIComponent('/omega')}`}
                  className="inline-flex items-center justify-center px-8 py-3 text-base font-medium rounded-lg bg-primary text-primary-foreground hover:bg-primary/90 transition-colors"
                >
                  <Icon icon="user" size="sm" className="mr-2" />
                  Sign In to Start
                </Link>
                <p className="text-sm text-foreground-tertiary">Sign in to start using Omega</p>
              </div>
            )}
          </div>

          {/* Error Message */}
          {error && (
            <div className="text-center mb-8">
              <p className="text-sm text-error">{error}</p>
            </div>
          )}

          {/* Sample Prompts */}
          <div className="space-y-4">
            <h2 className="text-sm font-medium text-foreground-tertiary text-center mb-6">
              {isAuthenticated ? 'Or try one of these examples' : 'Explore what Omega can do'}
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {SAMPLE_PROMPTS.map((prompt) => (
                <button
                  key={prompt.title}
                  type="button"
                  onClick={() => createConversation(prompt.prompt)}
                  disabled={isCreating || isSessionLoading}
                  className="p-4 bg-surface border border-border rounded-lg hover:border-foreground/20 hover:bg-surface-secondary/50 transition-all text-left group disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <div className="flex items-start gap-3">
                    <div className="p-2 rounded-lg bg-primary/10 text-primary group-hover:bg-primary/20 transition-colors">
                      <Icon icon={prompt.icon} size="sm" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h3 className="font-medium text-foreground mb-1">{prompt.title}</h3>
                      <p className="text-sm text-foreground-secondary line-clamp-2">
                        {prompt.description}
                      </p>
                    </div>
                  </div>
                </button>
              ))}
            </div>
          </div>

          {/* Features */}
          <div className="mt-16 pt-8 border-t border-border">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 text-center">
              <div>
                <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-success/10 mb-4">
                  <Icon icon="search" size="sm" className="text-success" />
                </div>
                <h3 className="font-medium text-foreground mb-2">Dynamic Discovery</h3>
                <p className="text-sm text-foreground-secondary">
                  Omega searches the entire TPMJS registry to find the perfect tools for your task
                </p>
              </div>
              <div>
                <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-info/10 mb-4">
                  <Icon icon="box" size="sm" className="text-info" />
                </div>
                <h3 className="font-medium text-foreground mb-2">Sandboxed Execution</h3>
                <p className="text-sm text-foreground-secondary">
                  All tools run in a secure sandbox environment for safe execution
                </p>
              </div>
              <div>
                <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-warning/10 mb-4">
                  <Icon icon="star" size="sm" className="text-warning" />
                </div>
                <h3 className="font-medium text-foreground mb-2">Intelligent Synthesis</h3>
                <p className="text-sm text-foreground-secondary">
                  Results are combined and presented in a clear, helpful response
                </p>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

input.content:
'use client';

import { Badge } from '@tpmjs/ui/Badge/Badge';
import { Button } from '@tpmjs/ui/Button/Button';
import { Icon } from '@tpmjs/ui/Icon/Icon';
import { Textarea } from '@tpmjs/ui/Textarea/Textarea';
import { registerBuiltInRenderers } from '@tpmjs/ui/ToolRenderer/registerBuiltInRenderers';
import { ToolRenderer } from '@tpmjs/ui/ToolRenderer/ToolRenderer';
import type { ToolPart, ToolState } from '@tpmjs/ui/ToolRenderer/types';
import Link from 'next/link';
import { useParams, useRouter } from 'next/navigation';
import { useCallback, useEffect, useRef, useState } from 'react';
import { Streamdown } from 'streamdown';
import { AppHeader } from '~/components/AppHeader';
import { EnvVarWarningBanner } from '~/components/omega/EnvVarWarningBanner';

// Initialize built-in tool renderers (idempotent)
registerBuiltInRenderers();

interface ToolDiscoveryInfo {
  staticTools?: string[];
  dynamicToolsLoaded?: string[];
  autoDiscoveredTools?: Array<{
    toolId: string;
    name: string;
    packageName: string;
    description: string;
  }>;
}

interface Message {
  id: string;
  role: 'USER' | 'ASSISTANT' | 'TOOL';
  content: string;
  toolCalls?: Array<{
    toolCallId: string;
    toolName: string;
    args?: unknown;
    output?: unknown;
  }>;
  inputTokens?: number;
  outputTokens?: number;
  createdAt: string;
  toolDiscovery?: ToolDiscoveryInfo;
}

interface ToolCall {
  toolCallId: string;
  toolName: string;
  input?: unknown;
  output?: unknown;
  status: 'pending' | 'running' | 'success' | 'error';
  isError?: boolean;
}

interface EnvVarWarning {
  toolId: string;
  toolName: string;
  packageName: string;
  envVar: {
    name: string;
    description: string;
    required: boolean;
  };
}

interface Conversation {
  id: string;
  title: string | null;
  executionState: string;
  inputTokensTotal: number;
  outputTokensTotal: number;
  createdAt: string;
  updatedAt: string;
}

/**
 * Convert ToolCall status to ToolState
 */
function statusToToolState(status: ToolCall['status']): ToolState {
  switch (status) {
    case 'pending':
      return 'partial-call';
    case 'running':
      return 'call';
    case 'success':
    case 'error':
      return 'result';
  }
}

/**
 * Convert ToolCall to ToolPart for rendering
 */
function toolCallToToolPart(tc: ToolCall): ToolPart {
  return {
    type: tc.status === 'success' || tc.status === 'error' ? 'tool-result' : 'tool-call',
    toolCallId: tc.toolCallId,
    toolName: tc.toolName,
    args: tc.input,
    result: tc.isError ? { error: tc.output } : tc.output,
    state: statusToToolState(tc.status),
  };
}

const CAPABILITY_ICONS = ['search', 'terminal', 'globe', 'database', 'mail'] as const;

/**
 * Omega Chat Page — Brutalist Command Center
 */
// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex chat page with multiple UI states and SSE handling
export default function OmegaChatPage(): React.ReactElement {
  const params = useParams();
  const router = useRouter();
  const conversationId = params.conversationId as string;

  const [conversation, setConversation] = useState<Conversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSending, setIsSending] = useState(false);
  const [streamingContent, setStreamingContent] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [toolCalls, setToolCalls] = useState<ToolCall[]>([]);
  const [viewMode, setViewMode] = useState<'chat' | 'debug'>('chat');
  const [messageToolDiscovery, setMessageToolDiscovery] = useState<Map<string, ToolDiscoveryInfo>>(
    new Map()
  );
  const [envWarnings, setEnvWarnings] = useState<EnvVarWarning[]>([]);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);

  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);
  const isNearBottomRef = useRef(true);

  // Fetch conversation details
  const fetchConversation = useCallback(async () => {
    try {
      const response = await fetch(`/api/omega/conversations/${conversationId}`);

      if (response.status === 404) {
        setError('Conversation not found');
        setIsLoading(false);
        return;
      }

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || 'Failed to fetch conversation');
      }

      const data = await response.json();
      const { messages: messageList, ...conversationData } = data.data;
      setConversation(conversationData);
      setMessages(messageList || []);
    } catch (err) {
      console.error('Failed to fetch conversation:', err);
      setError(err instanceof Error ? err.message : 'Failed to fetch conversation');
    } finally {
      setIsLoading(false);
    }
  }, [conversationId]);

  useEffect(() => {
    fetchConversation();
  }, [fetchConversation]);

  // Smart auto-scroll
  const handleScroll = useCallback(() => {
    const el = messagesContainerRef.current;
    if (!el) return;
    isNearBottomRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < 100;
  }, []);

  // biome-ignore lint/correctness/useExhaustiveDependencies: We intentionally trigger scroll when messages/streamingContent change
  useEffect(() => {
    if (isNearBottomRef.current && messagesContainerRef.current) {
      messagesContainerRef.current.scrollTop = messagesContainerRef.current.scrollHeight;
    }
  }, [messages, streamingContent]);

  // Check for initial prompt from landing page
  // biome-ignore lint/correctness/useExhaustiveDependencies: Only run on mount and when messages load
  useEffect(() => {
    const initialPrompt = sessionStorage.getItem(`omega_prompt_${conversationId}`);
    if (initialPrompt && messages.length === 0 && !isSending) {
      sessionStorage.removeItem(`omega_prompt_${conversationId}`);
      setInput(initialPrompt);
      const timer = setTimeout(() => {
        handleSendWithContent(initialPrompt);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [conversationId, messages.length]);

  // Stop button handler
  const handleStop = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
    }
    setIsSending(false);
    setStatusMessage(null);
    setStreamingContent((prev) => {
      if (prev) {
        const partialMessage: Message = {
          id: `partial-${Date.now()}`,
          role: 'ASSISTANT',
          content: prev,
          createdAt: new Date().toISOString(),
        };
        setMessages((msgs) => [...msgs, partialMessage]);
      }
      return '';
    });
    setToolCalls([]);
    inputRef.current?.focus();
  }, []);

  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Chat send handler with streaming and tool calls
  const handleSendWithContent = async (messageContent: string) => {
    if (!messageContent.trim() || isSending) return;

    setInput('');
    setIsSending(true);
    setStreamingContent('');
    setError(null);
    setToolCalls([]);
    setStatusMessage(null);

    const controller = new AbortController();
    abortControllerRef.current = controller;

    const userMessage: Message = {
      id: `temp-${Date.now()}`,
      role: 'USER',
      content: messageContent,
      createdAt: new Date().toISOString(),
    };
    setMessages((prev) => [...prev, userMessage]);

    let accumulatedContent = '';
    let completedToolCalls: ToolCall[] = [];

    try {
      const response = await fetch(`/api/omega/conversations/${conversationId}/messages`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: messageContent }),
        signal: controller.signal,
      });

      if (!response.ok) {
        let errorMessage = 'Failed to send message';
        try {
          const errorData = await response.json();
          errorMessage = errorData.error || errorMessage;
        } catch {
          errorMessage = `Server error: ${response.status} ${response.statusText}`;
        }
        throw new Error(errorMessage);
      }

      const reader = response.body?.getReader();
      if (!reader) throw new Error('No response body');

      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        let eventType = '';
        for (const line of lines) {
          if (line.startsWith('event: ')) {
            eventType = line.slice(7);
          } else if (line.startsWith('data: ')) {
            let data: unknown;
            try {
              data = JSON.parse(line.slice(6));
            } catch {
              console.warn('Failed to parse SSE data:', line.slice(6));
              continue;
            }

            const d = data as Record<string, unknown>;

            switch (eventType) {
              case 'status':
                if (d.message && typeof d.message === 'string') {
                  setStatusMessage(d.message);
                }
                break;
              case 'env.warning':
                if (d.missingEnvVars && Array.isArray(d.missingEnvVars)) {
                  setEnvWarnings(d.missingEnvVars as EnvVarWarning[]);
                }
                break;
              case 'message.delta':
                setStatusMessage(null);
                accumulatedContent += (d as { content: string }).content;
                setStreamingContent((prev) => prev + (d as { content: string }).content);
                break;
              case 'run.step.tool.started':
                setStatusMessage(null);
                setToolCalls((prev) => {
                  const updated = [
                    ...prev,
                    {
                      toolCallId: d.toolCallId as string,
                      toolName: d.toolName as string,
                      input: d.input,
                      status: 'running' as const,
                    },
                  ];
                  completedToolCalls = updated;
                  return updated;
                });
                break;
              case 'run.step.tool.completed':
                setToolCalls((prev) => {
                  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Tool call update logic
                  const updated = prev.map((tc) =>
                    tc.toolCallId === d.toolCallId
                      ? {
                          ...tc,
                          output: d.output,
                          status: d.isError ? ('error' as const) : ('success' as const),
                          isError: d.isError as boolean | undefined,
                        }
                      : tc
                  );
                  completedToolCalls = updated;
                  return updated;
                });
                break;
              case 'run.completed': {
                const assistantMessage: Message = {
                  id: (d.messageId as string) || `msg-${Date.now()}`,
                  role: 'ASSISTANT',
                  content: accumulatedContent,
                  toolCalls: completedToolCalls
                    .filter((tc) => tc.status === 'success' || tc.status === 'error')
                    .map((tc) => ({
                      toolCallId: tc.toolCallId,
                      toolName: tc.toolName,
                      args: tc.input,
                      output: tc.output,
                    })),
                  inputTokens: d.inputTokens as number,
                  outputTokens: d.outputTokens as number,
                  createdAt: new Date().toISOString(),
                };

                const toolResultEntries = completedToolCalls
                  .filter((tc) => tc.output !== undefined)
                  .map((tc) => ({
                    toolCallId: tc.toolCallId,
                    toolName: tc.toolName,
                    output: tc.output,
                  }));

                setMessages((prev) => {
                  const updated = [...prev, assistantMessage];
                  if (toolResultEntries.length > 0) {
                    updated.push({
                      id: `tool-${Date.now()}`,
                      role: 'TOOL',
                      content: 'Tool results',
                      toolCalls: toolResultEntries,
                      createdAt: new Date().toISOString(),
                    });
                  }
                  return updated;
                });

                if (conversation) {
                  setConversation({
                    ...conversation,
                    inputTokensTotal:
                      conversation.inputTokensTotal + ((d.inputTokens as number) || 0),
                    outputTokensTotal:
                      conversation.outputTokensTotal + ((d.outputTokens as number) || 0),
                    executionState: 'idle',
                  });
                }

                const toolDiscovery: ToolDiscoveryInfo = {
                  staticTools: d.staticTools as string[],
                  dynamicToolsLoaded: d.dynamicToolsLoaded as string[],
                  autoDiscoveredTools:
                    d.autoDiscoveredTools as ToolDiscoveryInfo['autoDiscoveredTools'],
                };
                setMessageToolDiscovery((prev) => {
                  const next = new Map(prev);
                  next.set(assistantMessage.id, toolDiscovery);
                  return next;
                });

                setStreamingContent('');
                setToolCalls([]);
                setStatusMessage(null);
                break;
              }
              case 'run.failed':
                throw new Error(d.error as string);
            }
          }
        }
      }
    } catch (err) {
      if (err instanceof DOMException && err.name === 'AbortError') {
        return;
      }
      console.error('Failed to send message:', err);
      setError(err instanceof Error ? err.message : 'Failed to send message');
      setMessages((prev) => prev.filter((m) => m.id !== userMessage.id));
    } finally {
      abortControllerRef.current = null;
      setIsSending(false);
      setStreamingContent('');
      setStatusMessage(null);
      inputRef.current?.focus();
    }
  };

  const handleSend = async () => {
    if (!input.trim() || isSending) return;
    await handleSendWithContent(input.trim());
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const startNewConversation = async () => {
    try {
      const response = await fetch('/api/omega/conversations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || 'Failed to create conversation');
      }

      const data = await response.json();
      router.push(`/omega/${data.data.id}`);
    } catch (err) {
      console.error('Failed to create conversation:', err);
      setError(err instanceof Error ? err.message : 'Failed to create conversation');
    }
  };

  // --- Loading State ---
  if (isLoading) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <div className="flex items-center justify-center h-[calc(100vh-64px)]">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 bg-primary animate-pulse" />
            <span className="font-mono text-sm text-foreground-secondary uppercase tracking-wider">
              loading session...
            </span>
          </div>
        </div>
      </div>
    );
  }

  // --- Error State (no conversation) ---
  if (error && !conversation) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <div className="flex items-center justify-center h-[calc(100vh-64px)]">
          <div className="text-center">
            <div className="w-14 h-14 border-2 border-foreground flex items-center justify-center mx-auto mb-4">
              <Icon icon="alertCircle" size="lg" />
            </div>
            <h2 className="font-mono font-bold text-foreground uppercase tracking-tight mb-2">
              Unable to Load Chat
            </h2>
            <p className="text-foreground-secondary font-mono text-sm mb-6">{error}</p>
            <Link href="/omega">
              <Button>Start New Conversation</Button>
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <AppHeader />

      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <div className="border-b-2 border-foreground bg-surface/50 px-4 py-3">
          <div className="flex items-center justify-between max-w-4xl mx-auto">
            <div className="flex items-center gap-3">
              <Link
                href="/omega"
                className="w-10 h-10 border border-border flex items-center justify-center hover:border-foreground transition-colors"
              >
                <Icon icon="arrowLeft" size="sm" className="text-foreground-secondary" />
              </Link>
              <div>
                <h1 className="font-mono uppercase tracking-tight font-bold text-foreground">
                  {conversation?.title || 'New Conversation'}
                </h1>
                <div className="flex items-center gap-2 text-sm text-foreground-tertiary">
                  <Badge variant="secondary" size="sm">
                    Omega
                  </Badge>
                  <span className="font-mono text-xs">GPT-4.1 Mini</span>
                  {conversation && (
                    <span className="font-mono text-xs">
                      {conversation.inputTokensTotal + conversation.outputTokensTotal} tokens
                    </span>
                  )}
                </div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <Link href="/omega/settings">
                <Button variant="ghost" size="sm">
                  <Icon icon="key" size="xs" className="mr-2" />
                  Settings
                </Button>
              </Link>
              <Button variant="ghost" size="sm" onClick={startNewConversation}>
                <Icon icon="plus" size="xs" className="mr-2" />
                New Chat
              </Button>
            </div>
          </div>

          {/* Segmented Tab Switcher */}
          <div className="flex mt-3 max-w-4xl mx-auto border border-border w-fit">
            <button
              type="button"
              onClick={() => setViewMode('chat')}
              className={`px-4 py-1.5 font-mono text-xs uppercase tracking-wider transition-colors ${
                viewMode === 'chat'
                  ? 'bg-foreground text-background'
                  : 'bg-transparent text-foreground-secondary hover:text-foreground'
              }`}
            >
              Chat
            </button>
            <button
              type="button"
              onClick={() => setViewMode('debug')}
              className={`px-4 py-1.5 font-mono text-xs uppercase tracking-wider transition-colors ${
                viewMode === 'debug'
                  ? 'bg-foreground text-background'
                  : 'bg-transparent text-foreground-secondary hover:text-foreground'
              }`}
            >
              Debug JSON
            </button>
          </div>
        </div>

        {/* Debug JSON View */}
        {viewMode === 'debug' && (
          <div className="flex-1 overflow-auto p-4 bg-background">
            <div className="max-w-4xl mx-auto space-y-6">
              <div className="flex items-start justify-between">
                <div>
                  <h2 className="font-mono font-bold text-foreground uppercase tracking-tight text-sm mb-2">
                    Messages with Tool Discovery ({messages.length} messages)
                  </h2>
                  <p className="text-xs text-foreground-tertiary font-mono">
                    Each message shows the tools discovered and loaded during that response.
                  </p>
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    const messagesWithTools = messages.map((m) => ({
                      ...m,
                      toolDiscovery: messageToolDiscovery.get(m.id) || null,
                    }));
                    navigator.clipboard.writeText(JSON.stringify(messagesWithTools, null, 2));
                  }}
                >
                  <Icon icon="copy" size="xs" className="mr-2" />
                  Copy All JSON
                </Button>
              </div>

              {/* biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Debug view with multiple conditional sections */}
              {messages.map((message, index) => {
                const discovery = messageToolDiscovery.get(message.id);
                return (
                  <div
                    key={message.id}
                    className="bg-surface-secondary border-2 border-border overflow-hidden"
                  >
                    <div className="px-4 py-3 border-b border-border/50 bg-surface/50">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          <span className="text-xs text-foreground-tertiary font-mono">
                            #{index + 1}
                          </span>
                          <Badge
                            variant={
                              message.role === 'USER'
                                ? 'secondary'
                                : message.role === 'ASSISTANT'
                                  ? 'default'
                                  : 'outline'
                            }
                            size="sm"
                          >
                            {message.role}
                          </Badge>
                          <span className="text-xs text-foreground-tertiary font-mono">
                            {message.id.slice(0, 8)}...
                          </span>
                        </div>
                        <span className="text-xs text-foreground-tertiary font-mono">
                          {new Date(message.createdAt).toLocaleTimeString()}
                        </span>
                      </div>
                    </div>

                    <div className="p-4 space-y-4">
                      <div>
                        <div className="text-[10px] uppercase tracking-wider text-foreground-tertiary font-mono mb-2">
                          Content
                        </div>
                        <pre className="text-xs font-mono bg-background/50 p-3 overflow-x-auto whitespace-pre-wrap max-h-48 overflow-y-auto">
                          {message.content || '(empty)'}
                        </pre>
                      </div>

                      {message.role === 'ASSISTANT' && discovery && (
                        <div className="space-y-3 pt-3 border-t border-border/50">
                          <div className="text-[10px] uppercase tracking-wider text-foreground-tertiary font-mono">
                            Tool Discovery for this Response
                          </div>

                          {discovery.staticTools && discovery.staticTools.length > 0 && (
                            <div>
                              <div className="text-xs text-foreground-secondary mb-1 font-mono">
                                Static Tools ({discovery.staticTools.length})
                              </div>
                              <div className="flex flex-wrap gap-1">
                                {discovery.staticTools.map((name) => (
                                  <span
                                    key={name}
                                    className="px-2 py-0.5 bg-blue-500/10 text-blue-500 text-[10px] font-mono"
                                  >
                                    {name}
                                  </span>
                                ))}
                              </div>
                            </div>
                          )}

                          {discovery.autoDiscoveredTools &&
                            discovery.autoDiscoveredTools.length > 0 && (
                              <div>
                                <div className="text-xs text-foreground-secondary mb-1 font-mono">
                                  Auto-Discovered via BM25 ({discovery.autoDiscoveredTools.length})
                                </div>
                                <div className="space-y-1">
                                  {discovery.autoDiscoveredTools.map((t) => (
                                    <div
                                      key={t.toolId}
                                      className="text-[10px] font-mono bg-background/50 px-2 py-1"
                                    >
                                      <span className="text-primary">{t.packageName}</span>
                                      <span className="text-foreground-tertiary">::</span>
                                      <span className="text-foreground">{t.name}</span>
                                      <span className="text-foreground-tertiary ml-2">
                                        - {t.description?.slice(0, 60)}
                                        {(t.description?.length || 0) > 60 ? '...' : ''}
                                      </span>
                                    </div>
                                  ))}
                                </div>
                              </div>
                            )}

                          {discovery.dynamicToolsLoaded &&
                            discovery.dynamicToolsLoaded.length > 0 && (
                              <div>
                                <div className="text-xs text-foreground-secondary mb-1 font-mono">
                                  Dynamic Tools Loaded ({discovery.dynamicToolsLoaded.length})
                                </div>
                                <div className="flex flex-wrap gap-1">
                                  {discovery.dynamicToolsLoaded.map((name) => (
                                    <span
                                      key={name}
                                      className="px-2 py-0.5 bg-primary/10 text-primary text-[10px] font-mono"
                                    >
                                      {name}
                                    </span>
                                  ))}
                                </div>
                              </div>
                            )}
                        </div>
                      )}

                      {message.toolCalls && message.toolCalls.length > 0 && (
                        <div className="pt-3 border-t border-border/50">
                          <div className="text-[10px] uppercase tracking-wider text-foreground-tertiary font-mono mb-2">
                            Tool Calls ({message.toolCalls.length})
                          </div>
                          <pre className="text-xs font-mono bg-background/50 p-3 overflow-x-auto whitespace-pre-wrap max-h-48 overflow-y-auto">
                            {JSON.stringify(message.toolCalls, null, 2)}
                          </pre>
                        </div>
                      )}

                      {(message.inputTokens || message.outputTokens) && (
                        <div className="text-[10px] text-foreground-tertiary font-mono pt-2 border-t border-border/50">
                          {message.inputTokens && <span>Input: {message.inputTokens}</span>}
                          {message.inputTokens && message.outputTokens && <span> | </span>}
                          {message.outputTokens && <span>Output: {message.outputTokens}</span>}
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}

              {messages.length === 0 && (
                <div className="text-center py-8 text-foreground-tertiary font-mono text-sm">
                  No messages yet. Start a conversation to see debug data.
                </div>
              )}
            </div>
          </div>
        )}

        {/* Chat View */}
        {viewMode === 'chat' && (
          <>
            {/* Messages */}
            <div className="flex-1 overflow-hidden">
              {messages.length === 0 && !streamingContent ? (
                /* Empty State */
                <div className="h-full flex items-center justify-center p-4">
                  <div className="text-center">
                    {/* Watermark */}
                    <div className="text-6xl md:text-8xl font-bold text-foreground/10 font-mono uppercase tracking-tighter mb-8 select-none">
                      OMEGA
                    </div>

                    {/* Capability Icons */}
                    <div className="flex items-center justify-center gap-3 mb-6">
                      {CAPABILITY_ICONS.map((icon, i) => (
                        <div
                          key={icon}
                          className="w-10 h-10 border border-border flex items-center justify-center animate-brutalist-entrance"
                          style={{ animationDelay: `${i * 100}ms` }}
                        >
                          <Icon icon={icon} size="sm" className="text-foreground-secondary" />
                        </div>
                      ))}
                    </div>

                    <p className="font-mono text-sm text-foreground-secondary max-w-sm mx-auto">
                      Describe what you need. Omega will discover and execute the right tools
                      from the TPMJS registry.
                    </p>
                  </div>
                </div>
              ) : (
                <div
                  ref={messagesContainerRef}
                  className="h-full overflow-y-auto"
                  onScroll={handleScroll}
                >
                  <div className="max-w-4xl mx-auto">
                    {messages.map((message) => (
                      <div key={message.id} className="px-4 py-2">
                        {/* USER message */}
                        {message.role === 'USER' && (
                          <div className="flex justify-end">
                            <div className="max-w-[80%] border-l-4 border-primary p-4 bg-primary/5">
                              <div className="text-sm whitespace-pre-wrap">{message.content}</div>
                            </div>
                          </div>
                        )}

                        {/* ASSISTANT message */}
                        {message.role === 'ASSISTANT' && message.content && (
                          <div className="flex justify-start">
                            <div className="max-w-[80%] border-l-4 border-foreground/20 p-4 bg-surface-secondary">
                              <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
                                <Streamdown>{message.content}</Streamdown>
                              </div>
                              {(message.inputTokens || message.outputTokens) && (
                                <div className="mt-2 pt-2 border-t border-border/50 font-mono uppercase tracking-wider text-[10px] text-foreground-tertiary">
                                  {message.inputTokens && (
                                    <span>In: {message.inputTokens}</span>
                                  )}
                                  {message.inputTokens && message.outputTokens && (
                                    <span> | </span>
                                  )}
                                  {message.outputTokens && (
                                    <span>Out: {message.outputTokens}</span>
                                  )}
                                </div>
                              )}
                            </div>
                          </div>
                        )}

                        {/* TOOL message */}
                        {message.role === 'TOOL' && message.toolCalls && (
                          <div className="flex justify-start">
                            <div className="max-w-[80%] space-y-2">
                              {message.toolCalls.map((tc) => (
                                <ToolRenderer
                                  key={tc.toolCallId}
                                  part={{
                                    type: 'tool-result',
                                    toolCallId: tc.toolCallId,
                                    toolName: tc.toolName,
                                    args: tc.args,
                                    result: tc.output,
                                    state: 'result',
                                  }}
                                  isStreaming={false}
                                />
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    ))}

                    {/* Tool Execution Pipeline */}
                    {toolCalls.length > 0 && (
                      <div className="px-4 pb-4">
                        {/* Pipeline header */}
                        <div className="flex items-center gap-2 mb-3">
                          <div className="w-1.5 h-1.5 bg-primary animate-pulse" />
                          <span className="font-mono text-xs text-foreground-secondary uppercase tracking-wider">
                            executing {toolCalls.length} tool{toolCalls.length !== 1 ? 's' : ''}
                          </span>
                          <div className="h-px bg-border flex-1" />
                        </div>

                        {/* Vertical pipeline */}
                        <div className="border-l-2 border-primary/30 pl-4 space-y-2">
                          {toolCalls.map((tc) => (
                            <div key={tc.toolCallId}>
                              <ToolRenderer
                                part={toolCallToToolPart(tc)}
                                isStreaming={tc.status === 'running'}
                              />
                            </div>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Streaming content */}
                    {streamingContent && (
                      <div className="px-4 pb-4">
                        <div className="flex justify-start">
                          <div className="max-w-[80%] border-l-4 border-foreground/20 p-4 bg-surface-secondary">
                            <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
                              <Streamdown>{streamingContent}</Streamdown>
                            </div>
                            <span className="inline-block w-2 h-4 bg-primary animate-pulse ml-1" />
                          </div>
                        </div>
                      </div>
                    )}

                    {/* Thinking indicator */}
                    {isSending && !streamingContent && toolCalls.length === 0 && (
                      <div className="px-4 pb-4">
                        <div className="flex justify-start">
                          <div className="border-l-4 border-primary p-4 bg-surface-secondary">
                            <div className="flex items-center gap-2 text-foreground-secondary">
                              <div className="w-2 h-2 bg-primary animate-pulse" />
                              <span className="font-mono text-sm">
                                {statusMessage || 'discovering tools...'}
                              </span>
                            </div>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* Environment Variable Warnings */}
            {envWarnings.length > 0 && (
              <div className="max-w-4xl mx-auto">
                <EnvVarWarningBanner warnings={envWarnings} onDismiss={() => setEnvWarnings([])} />
              </div>
            )}

            {/* Error Message */}
            {error && (
              <div className="px-4 py-2 bg-error/10 border-t border-error/20">
                <p className="text-sm text-error max-w-4xl mx-auto font-mono">{error}</p>
              </div>
            )}

            {/* Input Area */}
            <div className="border-t-2 border-foreground p-4">
              <div className="max-w-4xl mx-auto">
                <div className="border border-border focus-within:border-foreground transition-colors">
                  <Textarea
                    ref={inputRef}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Ask Omega anything..."
                    rows={1}
                    resize="none"
                    className="border-none bg-transparent flex-1 min-h-[48px] max-h-[200px]"
                    style={{
                      height: 'auto',
                      minHeight: '48px',
                    }}
                    onInput={(e) => {
                      const target = e.target as HTMLTextAreaElement;
                      target.style.height = 'auto';
                      target.style.height = `${Math.min(target.scrollHeight, 200)}px`;
                    }}
                  />
                  <div className="flex items-center justify-between px-3 pb-2">
                    <span className="font-mono text-xs text-foreground-tertiary uppercase tracking-wider">
                      Enter to send / Shift+Enter for new line
                    </span>
                    <div className="flex items-center gap-2">
                      {conversation && (
                        <span className="font-mono text-xs text-foreground-tertiary">
                          {conversation.inputTokensTotal + conversation.outputTokensTotal} tokens
                        </span>
                      )}
                      {isSending ? (
                        <Button onClick={handleStop} variant="destructive" size="sm">
                          <Icon icon="x" size="xs" />
                        </Button>
                      ) : (
                        <Button onClick={handleSend} disabled={!input.trim()} size="sm">
                          <Icon icon="send" size="xs" />
                        </Button>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

toolUseResult.content:
'use client';

import { Badge } from '@tpmjs/ui/Badge/Badge';
import { Button } from '@tpmjs/ui/Button/Button';
import { Icon } from '@tpmjs/ui/Icon/Icon';
import { Textarea } from '@tpmjs/ui/Textarea/Textarea';
import { registerBuiltInRenderers } from '@tpmjs/ui/ToolRenderer/registerBuiltInRenderers';
import { ToolRenderer } from '@tpmjs/ui/ToolRenderer/ToolRenderer';
import type { ToolPart, ToolState } from '@tpmjs/ui/ToolRenderer/types';
import Link from 'next/link';
import { useParams, useRouter } from 'next/navigation';
import { useCallback, useEffect, useRef, useState } from 'react';
import { Streamdown } from 'streamdown';
import { AppHeader } from '~/components/AppHeader';
import { EnvVarWarningBanner } from '~/components/omega/EnvVarWarningBanner';

// Initialize built-in tool renderers (idempotent)
registerBuiltInRenderers();

interface ToolDiscoveryInfo {
  staticTools?: string[];
  dynamicToolsLoaded?: string[];
  autoDiscoveredTools?: Array<{
    toolId: string;
    name: string;
    packageName: string;
    description: string;
  }>;
}

interface Message {
  id: string;
  role: 'USER' | 'ASSISTANT' | 'TOOL';
  content: string;
  toolCalls?: Array<{
    toolCallId: string;
    toolName: string;
    args?: unknown;
    output?: unknown;
  }>;
  inputTokens?: number;
  outputTokens?: number;
  createdAt: string;
  toolDiscovery?: ToolDiscoveryInfo;
}

interface ToolCall {
  toolCallId: string;
  toolName: string;
  input?: unknown;
  output?: unknown;
  status: 'pending' | 'running' | 'success' | 'error';
  isError?: boolean;
}

interface EnvVarWarning {
  toolId: string;
  toolName: string;
  packageName: string;
  envVar: {
    name: string;
    description: string;
    required: boolean;
  };
}

interface Conversation {
  id: string;
  title: string | null;
  executionState: string;
  inputTokensTotal: number;
  outputTokensTotal: number;
  createdAt: string;
  updatedAt: string;
}

/**
 * Convert ToolCall status to ToolState
 */
function statusToToolState(status: ToolCall['status']): ToolState {
  switch (status) {
    case 'pending':
      return 'partial-call';
    case 'running':
      return 'call';
    case 'success':
    case 'error':
      return 'result';
  }
}

/**
 * Convert ToolCall to ToolPart for rendering
 */
function toolCallToToolPart(tc: ToolCall): ToolPart {
  return {
    type: tc.status === 'success' || tc.status === 'error' ? 'tool-result' : 'tool-call',
    toolCallId: tc.toolCallId,
    toolName: tc.toolName,
    args: tc.input,
    result: tc.isError ? { error: tc.output } : tc.output,
    state: statusToToolState(tc.status),
  };
}

const CAPABILITY_ICONS = ['search', 'terminal', 'globe', 'database', 'mail'] as const;

/**
 * Omega Chat Page — Brutalist Command Center
 */
// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex chat page with multiple UI states and SSE handling
export default function OmegaChatPage(): React.ReactElement {
  const params = useParams();
  const router = useRouter();
  const conversationId = params.conversationId as string;

  const [conversation, setConversation] = useState<Conversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSending, setIsSending] = useState(false);
  const [streamingContent, setStreamingContent] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [toolCalls, setToolCalls] = useState<ToolCall[]>([]);
  const [viewMode, setViewMode] = useState<'chat' | 'debug'>('chat');
  const [messageToolDiscovery, setMessageToolDiscovery] = useState<Map<string, ToolDiscoveryInfo>>(
    new Map()
  );
  const [envWarnings, setEnvWarnings] = useState<EnvVarWarning[]>([]);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);

  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);
  const isNearBottomRef = useRef(true);

  // Fetch conversation details
  const fetchConversation = useCallback(async () => {
    try {
      const response = await fetch(`/api/omega/conversations/${conversationId}`);

      if (response.status === 404) {
        setError('Conversation not found');
        setIsLoading(false);
        return;
      }

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || 'Failed to fetch conversation');
      }

      const data = await response.json();
      const { messages: messageList, ...conversationData } = data.data;
      setConversation(conversationData);
      setMessages(messageList || []);
    } catch (err) {
      console.error('Failed to fetch conversation:', err);
      setError(err instanceof Error ? err.message : 'Failed to fetch conversation');
    } finally {
      setIsLoading(false);
    }
  }, [conversationId]);

  useEffect(() => {
    fetchConversation();
  }, [fetchConversation]);

  // Smart auto-scroll
  const handleScroll = useCallback(() => {
    const el = messagesContainerRef.current;
    if (!el) return;
    isNearBottomRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < 100;
  }, []);

  // biome-ignore lint/correctness/useExhaustiveDependencies: We intentionally trigger scroll when messages/streamingContent change
  useEffect(() => {
    if (isNearBottomRef.current && messagesContainerRef.current) {
      messagesContainerRef.current.scrollTop = messagesContainerRef.current.scrollHeight;
    }
  }, [messages, streamingContent]);

  // Check for initial prompt from landing page
  // biome-ignore lint/correctness/useExhaustiveDependencies: Only run on mount and when messages load
  useEffect(() => {
    const initialPrompt = sessionStorage.getItem(`omega_prompt_${conversationId}`);
    if (initialPrompt && messages.length === 0 && !isSending) {
      sessionStorage.removeItem(`omega_prompt_${conversationId}`);
      setInput(initialPrompt);
      const timer = setTimeout(() => {
        handleSendWithContent(initialPrompt);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [conversationId, messages.length]);

  // Stop button handler
  const handleStop = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
    }
    setIsSending(false);
    setStatusMessage(null);
    setStreamingContent((prev) => {
      if (prev) {
        const partialMessage: Message = {
          id: `partial-${Date.now()}`,
          role: 'ASSISTANT',
          content: prev,
          createdAt: new Date().toISOString(),
        };
        setMessages((msgs) => [...msgs, partialMessage]);
      }
      return '';
    });
    setToolCalls([]);
    inputRef.current?.focus();
  }, []);

  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Chat send handler with streaming and tool calls
  const handleSendWithContent = async (messageContent: string) => {
    if (!messageContent.trim() || isSending) return;

    setInput('');
    setIsSending(true);
    setStreamingContent('');
    setError(null);
    setToolCalls([]);
    setStatusMessage(null);

    const controller = new AbortController();
    abortControllerRef.current = controller;

    const userMessage: Message = {
      id: `temp-${Date.now()}`,
      role: 'USER',
      content: messageContent,
      createdAt: new Date().toISOString(),
    };
    setMessages((prev) => [...prev, userMessage]);

    let accumulatedContent = '';
    let completedToolCalls: ToolCall[] = [];

    try {
      const response = await fetch(`/api/omega/conversations/${conversationId}/messages`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: messageContent }),
        signal: controller.signal,
      });

      if (!response.ok) {
        let errorMessage = 'Failed to send message';
        try {
          const errorData = await response.json();
          errorMessage = errorData.error || errorMessage;
        } catch {
          errorMessage = `Server error: ${response.status} ${response.statusText}`;
        }
        throw new Error(errorMessage);
      }

      const reader = response.body?.getReader();
      if (!reader) throw new Error('No response body');

      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        let eventType = '';
        for (const line of lines) {
          if (line.startsWith('event: ')) {
            eventType = line.slice(7);
          } else if (line.startsWith('data: ')) {
            let data: unknown;
            try {
              data = JSON.parse(line.slice(6));
            } catch {
              console.warn('Failed to parse SSE data:', line.slice(6));
              continue;
            }

            const d = data as Record<string, unknown>;

            switch (eventType) {
              case 'status':
                if (d.message && typeof d.message === 'string') {
                  setStatusMessage(d.message);
                }
                break;
              case 'env.warning':
                if (d.missingEnvVars && Array.isArray(d.missingEnvVars)) {
                  setEnvWarnings(d.missingEnvVars as EnvVarWarning[]);
                }
                break;
              case 'message.delta':
                setStatusMessage(null);
                accumulatedContent += (d as { content: string }).content;
                setStreamingContent((prev) => prev + (d as { content: string }).content);
                break;
              case 'run.step.tool.started':
                setStatusMessage(null);
                setToolCalls((prev) => {
                  const updated = [
                    ...prev,
                    {
                      toolCallId: d.toolCallId as string,
                      toolName: d.toolName as string,
                      input: d.input,
                      status: 'running' as const,
                    },
                  ];
                  completedToolCalls = updated;
                  return updated;
                });
                break;
              case 'run.step.tool.completed':
                setToolCalls((prev) => {
                  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Tool call update logic
                  const updated = prev.map((tc) =>
                    tc.toolCallId === d.toolCallId
                      ? {
                          ...tc,
                          output: d.output,
                          status: d.isError ? ('error' as const) : ('success' as const),
                          isError: d.isError as boolean | undefined,
                        }
                      : tc
                  );
                  completedToolCalls = updated;
                  return updated;
                });
                break;
              case 'run.completed': {
                const assistantMessage: Message = {
                  id: (d.messageId as string) || `msg-${Date.now()}`,
                  role: 'ASSISTANT',
                  content: accumulatedContent,
                  toolCalls: completedToolCalls
                    .filter((tc) => tc.status === 'success' || tc.status === 'error')
                    .map((tc) => ({
                      toolCallId: tc.toolCallId,
                      toolName: tc.toolName,
                      args: tc.input,
                      output: tc.output,
                    })),
                  inputTokens: d.inputTokens as number,
                  outputTokens: d.outputTokens as number,
                  createdAt: new Date().toISOString(),
                };

                const toolResultEntries = completedToolCalls
                  .filter((tc) => tc.output !== undefined)
                  .map((tc) => ({
                    toolCallId: tc.toolCallId,
                    toolName: tc.toolName,
                    output: tc.output,
                  }));

                setMessages((prev) => {
                  const updated = [...prev, assistantMessage];
                  if (toolResultEntries.length > 0) {
                    updated.push({
                      id: `tool-${Date.now()}`,
                      role: 'TOOL',
                      content: 'Tool results',
                      toolCalls: toolResultEntries,
                      createdAt: new Date().toISOString(),
                    });
                  }
                  return updated;
                });

                if (conversation) {
                  setConversation({
                    ...conversation,
                    inputTokensTotal:
                      conversation.inputTokensTotal + ((d.inputTokens as number) || 0),
                    outputTokensTotal:
                      conversation.outputTokensTotal + ((d.outputTokens as number) || 0),
                    executionState: 'idle',
                  });
                }

                const toolDiscovery: ToolDiscoveryInfo = {
                  staticTools: d.staticTools as string[],
                  dynamicToolsLoaded: d.dynamicToolsLoaded as string[],
                  autoDiscoveredTools:
                    d.autoDiscoveredTools as ToolDiscoveryInfo['autoDiscoveredTools'],
                };
                setMessageToolDiscovery((prev) => {
                  const next = new Map(prev);
                  next.set(assistantMessage.id, toolDiscovery);
                  return next;
                });

                setStreamingContent('');
                setToolCalls([]);
                setStatusMessage(null);
                break;
              }
              case 'run.failed':
                throw new Error(d.error as string);
            }
          }
        }
      }
    } catch (err) {
      if (err instanceof DOMException && err.name === 'AbortError') {
        return;
      }
      console.error('Failed to send message:', err);
      setError(err instanceof Error ? err.message : 'Failed to send message');
      setMessages((prev) => prev.filter((m) => m.id !== userMessage.id));
    } finally {
      abortControllerRef.current = null;
      setIsSending(false);
      setStreamingContent('');
      setStatusMessage(null);
      inputRef.current?.focus();
    }
  };

  const handleSend = async () => {
    if (!input.trim() || isSending) return;
    await handleSendWithContent(input.trim());
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const startNewConversation = async () => {
    try {
      const response = await fetch('/api/omega/conversations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || 'Failed to create conversation');
      }

      const data = await response.json();
      router.push(`/omega/${data.data.id}`);
    } catch (err) {
      console.error('Failed to create conversation:', err);
      setError(err instanceof Error ? err.message : 'Failed to create conversation');
    }
  };

  // --- Loading State ---
  if (isLoading) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <div className="flex items-center justify-center h-[calc(100vh-64px)]">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 bg-primary animate-pulse" />
            <span className="font-mono text-sm text-foreground-secondary uppercase tracking-wider">
              loading session...
            </span>
          </div>
        </div>
      </div>
    );
  }

  // --- Error State (no conversation) ---
  if (error && !conversation) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <div className="flex items-center justify-center h-[calc(100vh-64px)]">
          <div className="text-center">
            <div className="w-14 h-14 border-2 border-foreground flex items-center justify-center mx-auto mb-4">
              <Icon icon="alertCircle" size="lg" />
            </div>
            <h2 className="font-mono font-bold text-foreground uppercase tracking-tight mb-2">
              Unable to Load Chat
            </h2>
            <p className="text-foreground-secondary font-mono text-sm mb-6">{error}</p>
            <Link href="/omega">
              <Button>Start New Conversation</Button>
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <AppHeader />

      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <div className="border-b-2 border-foreground bg-surface/50 px-4 py-3">
          <div className="flex items-center justify-between max-w-4xl mx-auto">
            <div className="flex items-center gap-3">
              <Link
                href="/omega"
                className="w-10 h-10 border border-border flex items-center justify-center hover:border-foreground transition-colors"
              >
                <Icon icon="arrowLeft" size="sm" className="text-foreground-secondary" />
              </Link>
              <div>
                <h1 className="font-mono uppercase tracking-tight font-bold text-foreground">
                  {conversation?.title || 'New Conversation'}
                </h1>
                <div className="flex items-center gap-2 text-sm text-foreground-tertiary">
                  <Badge variant="secondary" size="sm">
                    Omega
                  </Badge>
                  <span className="font-mono text-xs">GPT-4.1 Mini</span>
                  {conversation && (
                    <span className="font-mono text-xs">
                      {conversation.inputTokensTotal + conversation.outputTokensTotal} tokens
                    </span>
                  )}
                </div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <Link href="/omega/settings">
                <Button variant="ghost" size="sm">
                  <Icon icon="key" size="xs" className="mr-2" />
                  Settings
                </Button>
              </Link>
              <Button variant="ghost" size="sm" onClick={startNewConversation}>
                <Icon icon="plus" size="xs" className="mr-2" />
                New Chat
              </Button>
            </div>
          </div>

          {/* Segmented Tab Switcher */}
          <div className="flex mt-3 max-w-4xl mx-auto border border-border w-fit">
            <button
              type="button"
              onClick={() => setViewMode('chat')}
              className={`px-4 py-1.5 font-mono text-xs uppercase tracking-wider transition-colors ${
                viewMode === 'chat'
                  ? 'bg-foreground text-background'
                  : 'bg-transparent text-foreground-secondary hover:text-foreground'
              }`}
            >
              Chat
            </button>
            <button
              type="button"
              onClick={() => setViewMode('debug')}
              className={`px-4 py-1.5 font-mono text-xs uppercase tracking-wider transition-colors ${
                viewMode === 'debug'
                  ? 'bg-foreground text-background'
                  : 'bg-transparent text-foreground-secondary hover:text-foreground'
              }`}
            >
              Debug JSON
            </button>
          </div>
        </div>

        {/* Debug JSON View */}
        {viewMode === 'debug' && (
          <div className="flex-1 overflow-auto p-4 bg-background">
            <div className="max-w-4xl mx-auto space-y-6">
              <div className="flex items-start justify-between">
                <div>
                  <h2 className="font-mono font-bold text-foreground uppercase tracking-tight text-sm mb-2">
                    Messages with Tool Discovery ({messages.length} messages)
                  </h2>
                  <p className="text-xs text-foreground-tertiary font-mono">
                    Each message shows the tools discovered and loaded during that response.
                  </p>
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    const messagesWithTools = messages.map((m) => ({
                      ...m,
                      toolDiscovery: messageToolDiscovery.get(m.id) || null,
                    }));
                    navigator.clipboard.writeText(JSON.stringify(messagesWithTools, null, 2));
                  }}
                >
                  <Icon icon="copy" size="xs" className="mr-2" />
                  Copy All JSON
                </Button>
              </div>

              {/* biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Debug view with multiple conditional sections */}
              {messages.map((message, index) => {
                const discovery = messageToolDiscovery.get(message.id);
                return (
                  <div
                    key={message.id}
                    className="bg-surface-secondary border-2 border-border overflow-hidden"
                  >
                    <div className="px-4 py-3 border-b border-border/50 bg-surface/50">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          <span className="text-xs text-foreground-tertiary font-mono">
                            #{index + 1}
                          </span>
                          <Badge
                            variant={
                              message.role === 'USER'
                                ? 'secondary'
                                : message.role === 'ASSISTANT'
                                  ? 'default'
                                  : 'outline'
                            }
                            size="sm"
                          >
                            {message.role}
                          </Badge>
                          <span className="text-xs text-foreground-tertiary font-mono">
                            {message.id.slice(0, 8)}...
                          </span>
                        </div>
                        <span className="text-xs text-foreground-tertiary font-mono">
                          {new Date(message.createdAt).toLocaleTimeString()}
                        </span>
                      </div>
                    </div>

                    <div className="p-4 space-y-4">
                      <div>
                        <div className="text-[10px] uppercase tracking-wider text-foreground-tertiary font-mono mb-2">
                          Content
                        </div>
                        <pre className="text-xs font-mono bg-background/50 p-3 overflow-x-auto whitespace-pre-wrap max-h-48 overflow-y-auto">
                          {message.content || '(empty)'}
                        </pre>
                      </div>

                      {message.role === 'ASSISTANT' && discovery && (
                        <div className="space-y-3 pt-3 border-t border-border/50">
                          <div className="text-[10px] uppercase tracking-wider text-foreground-tertiary font-mono">
                            Tool Discovery for this Response
                          </div>

                          {discovery.staticTools && discovery.staticTools.length > 0 && (
                            <div>
                              <div className="text-xs text-foreground-secondary mb-1 font-mono">
                                Static Tools ({discovery.staticTools.length})
                              </div>
                              <div className="flex flex-wrap gap-1">
                                {discovery.staticTools.map((name) => (
                                  <span
                                    key={name}
                                    className="px-2 py-0.5 bg-blue-500/10 text-blue-500 text-[10px] font-mono"
                                  >
                                    {name}
                                  </span>
                                ))}
                              </div>
                            </div>
                          )}

                          {discovery.autoDiscoveredTools &&
                            discovery.autoDiscoveredTools.length > 0 && (
                              <div>
                                <div className="text-xs text-foreground-secondary mb-1 font-mono">
                                  Auto-Discovered via BM25 ({discovery.autoDiscoveredTools.length})
                                </div>
                                <div className="space-y-1">
                                  {discovery.autoDiscoveredTools.map((t) => (
                                    <div
                                      key={t.toolId}
                                      className="text-[10px] font-mono bg-background/50 px-2 py-1"
                                    >
                                      <span className="text-primary">{t.packageName}</span>
                                      <span className="text-foreground-tertiary">::</span>
                                      <span className="text-foreground">{t.name}</span>
                                      <span className="text-foreground-tertiary ml-2">
                                        - {t.description?.slice(0, 60)}
                                        {(t.description?.length || 0) > 60 ? '...' : ''}
                                      </span>
                                    </div>
                                  ))}
                                </div>
                              </div>
                            )}

                          {discovery.dynamicToolsLoaded &&
                            discovery.dynamicToolsLoaded.length > 0 && (
                              <div>
                                <div className="text-xs text-foreground-secondary mb-1 font-mono">
                                  Dynamic Tools Loaded ({discovery.dynamicToolsLoaded.length})
                                </div>
                                <div className="flex flex-wrap gap-1">
                                  {discovery.dynamicToolsLoaded.map((name) => (
                                    <span
                                      key={name}
                                      className="px-2 py-0.5 bg-primary/10 text-primary text-[10px] font-mono"
                                    >
                                      {name}
                                    </span>
                                  ))}
                                </div>
                              </div>
                            )}
                        </div>
                      )}

                      {message.toolCalls && message.toolCalls.length > 0 && (
                        <div className="pt-3 border-t border-border/50">
                          <div className="text-[10px] uppercase tracking-wider text-foreground-tertiary font-mono mb-2">
                            Tool Calls ({message.toolCalls.length})
                          </div>
                          <pre className="text-xs font-mono bg-background/50 p-3 overflow-x-auto whitespace-pre-wrap max-h-48 overflow-y-auto">
                            {JSON.stringify(message.toolCalls, null, 2)}
                          </pre>
                        </div>
                      )}

                      {(message.inputTokens || message.outputTokens) && (
                        <div className="text-[10px] text-foreground-tertiary font-mono pt-2 border-t border-border/50">
                          {message.inputTokens && <span>Input: {message.inputTokens}</span>}
                          {message.inputTokens && message.outputTokens && <span> | </span>}
                          {message.outputTokens && <span>Output: {message.outputTokens}</span>}
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}

              {messages.length === 0 && (
                <div className="text-center py-8 text-foreground-tertiary font-mono text-sm">
                  No messages yet. Start a conversation to see debug data.
                </div>
              )}
            </div>
          </div>
        )}

        {/* Chat View */}
        {viewMode === 'chat' && (
          <>
            {/* Messages */}
            <div className="flex-1 overflow-hidden">
              {messages.length === 0 && !streamingContent ? (
                /* Empty State */
                <div className="h-full flex items-center justify-center p-4">
                  <div className="text-center">
                    {/* Watermark */}
                    <div className="text-6xl md:text-8xl font-bold text-foreground/10 font-mono uppercase tracking-tighter mb-8 select-none">
                      OMEGA
                    </div>

                    {/* Capability Icons */}
                    <div className="flex items-center justify-center gap-3 mb-6">
                      {CAPABILITY_ICONS.map((icon, i) => (
                        <div
                          key={icon}
                          className="w-10 h-10 border border-border flex items-center justify-center animate-brutalist-entrance"
                          style={{ animationDelay: `${i * 100}ms` }}
                        >
                          <Icon icon={icon} size="sm" className="text-foreground-secondary" />
                        </div>
                      ))}
                    </div>

                    <p className="font-mono text-sm text-foreground-secondary max-w-sm mx-auto">
                      Describe what you need. Omega will discover and execute the right tools
                      from the TPMJS registry.
                    </p>
                  </div>
                </div>
              ) : (
                <div
                  ref={messagesContainerRef}
                  className="h-full overflow-y-auto"
                  onScroll={handleScroll}
                >
                  <div className="max-w-4xl mx-auto">
                    {messages.map((message) => (
                      <div key={message.id} className="px-4 py-2">
                        {/* USER message */}
                        {message.role === 'USER' && (
                          <div className="flex justify-end">
                            <div className="max-w-[80%] border-l-4 border-primary p-4 bg-primary/5">
                              <div className="text-sm whitespace-pre-wrap">{message.content}</div>
                            </div>
                          </div>
                        )}

                        {/* ASSISTANT message */}
                        {message.role === 'ASSISTANT' && message.content && (
                          <div className="flex justify-start">
                            <div className="max-w-[80%] border-l-4 border-foreground/20 p-4 bg-surface-secondary">
                              <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
                                <Streamdown>{message.content}</Streamdown>
                              </div>
                              {(message.inputTokens || message.outputTokens) && (
                                <div className="mt-2 pt-2 border-t border-border/50 font-mono uppercase tracking-wider text-[10px] text-foreground-tertiary">
                                  {message.inputTokens && (
                                    <span>In: {message.inputTokens}</span>
                                  )}
                                  {message.inputTokens && message.outputTokens && (
                                    <span> | </span>
                                  )}
                                  {message.outputTokens && (
                                    <span>Out: {message.outputTokens}</span>
                                  )}
                                </div>
                              )}
                            </div>
                          </div>
                        )}

                        {/* TOOL message */}
                        {message.role === 'TOOL' && message.toolCalls && (
                          <div className="flex justify-start">
                            <div className="max-w-[80%] space-y-2">
                              {message.toolCalls.map((tc) => (
                                <ToolRenderer
                                  key={tc.toolCallId}
                                  part={{
                                    type: 'tool-result',
                                    toolCallId: tc.toolCallId,
                                    toolName: tc.toolName,
                                    args: tc.args,
                                    result: tc.output,
                                    state: 'result',
                                  }}
                                  isStreaming={false}
                                />
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    ))}

                    {/* Tool Execution Pipeline */}
                    {toolCalls.length > 0 && (
                      <div className="px-4 pb-4">
                        {/* Pipeline header */}
                        <div className="flex items-center gap-2 mb-3">
                          <div className="w-1.5 h-1.5 bg-primary animate-pulse" />
                          <span className="font-mono text-xs text-foreground-secondary uppercase tracking-wider">
                            executing {toolCalls.length} tool{toolCalls.length !== 1 ? 's' : ''}
                          </span>
                          <div className="h-px bg-border flex-1" />
                        </div>

                        {/* Vertical pipeline */}
                        <div className="border-l-2 border-primary/30 pl-4 space-y-2">
                          {toolCalls.map((tc) => (
                            <div key={tc.toolCallId}>
                              <ToolRenderer
                                part={toolCallToToolPart(tc)}
                                isStreaming={tc.status === 'running'}
                              />
                            </div>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Streaming content */}
                    {streamingContent && (
                      <div className="px-4 pb-4">
                        <div className="flex justify-start">
                          <div className="max-w-[80%] border-l-4 border-foreground/20 p-4 bg-surface-secondary">
                            <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
                              <Streamdown>{streamingContent}</Streamdown>
                            </div>
                            <span className="inline-block w-2 h-4 bg-primary animate-pulse ml-1" />
                          </div>
                        </div>
                      </div>
                    )}

                    {/* Thinking indicator */}
                    {isSending && !streamingContent && toolCalls.length === 0 && (
                      <div className="px-4 pb-4">
                        <div className="flex justify-start">
                          <div className="border-l-4 border-primary p-4 bg-surface-secondary">
                            <div className="flex items-center gap-2 text-foreground-secondary">
                              <div className="w-2 h-2 bg-primary animate-pulse" />
                              <span className="font-mono text-sm">
                                {statusMessage || 'discovering tools...'}
                              </span>
                            </div>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* Environment Variable Warnings */}
            {envWarnings.length > 0 && (
              <div className="max-w-4xl mx-auto">
                <EnvVarWarningBanner warnings={envWarnings} onDismiss={() => setEnvWarnings([])} />
              </div>
            )}

            {/* Error Message */}
            {error && (
              <div className="px-4 py-2 bg-error/10 border-t border-error/20">
                <p className="text-sm text-error max-w-4xl mx-auto font-mono">{error}</p>
              </div>
            )}

            {/* Input Area */}
            <div className="border-t-2 border-foreground p-4">
              <div className="max-w-4xl mx-auto">
                <div className="border border-border focus-within:border-foreground transition-colors">
                  <Textarea
                    ref={inputRef}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Ask Omega anything..."
                    rows={1}
                    resize="none"
                    className="border-none bg-transparent flex-1 min-h-[48px] max-h-[200px]"
                    style={{
                      height: 'auto',
                      minHeight: '48px',
                    }}
                    onInput={(e) => {
                      const target = e.target as HTMLTextAreaElement;
                      target.style.height = 'auto';
                      target.style.height = `${Math.min(target.scrollHeight, 200)}px`;
                    }}
                  />
                  <div className="flex items-center justify-between px-3 pb-2">
                    <span className="font-mono text-xs text-foreground-tertiary uppercase tracking-wider">
                      Enter to send / Shift+Enter for new line
                    </span>
                    <div className="flex items-center gap-2">
                      {conversation && (
                        <span className="font-mono text-xs text-foreground-tertiary">
                          {conversation.inputTokensTotal + conversation.outputTokensTotal} tokens
                        </span>
                      )}
                      {isSending ? (
                        <Button onClick={handleStop} variant="destructive" size="sm">
                          <Icon icon="x" size="xs" />
                        </Button>
                      ) : (
                        <Button onClick={handleSend} disabled={!input.trim()} size="sm">
                          <Icon icon="send" size="xs" />
                        </Button>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

toolUseResult.originalFile:
'use client';

import { Badge } from '@tpmjs/ui/Badge/Badge';
import { Button } from '@tpmjs/ui/Button/Button';
import { Icon } from '@tpmjs/ui/Icon/Icon';
import { Textarea } from '@tpmjs/ui/Textarea/Textarea';
import { registerBuiltInRenderers } from '@tpmjs/ui/ToolRenderer/registerBuiltInRenderers';
import { ToolRenderer } from '@tpmjs/ui/ToolRenderer/ToolRenderer';
import type { ToolPart, ToolState } from '@tpmjs/ui/ToolRenderer/types';
import Link from 'next/link';
import { useParams, useRouter } from 'next/navigation';
import { useCallback, useEffect, useRef, useState } from 'react';
import { Streamdown } from 'streamdown';
import { AppHeader } from '~/components/AppHeader';
import { EnvVarWarningBanner } from '~/components/omega/EnvVarWarningBanner';

// Initialize built-in tool renderers (idempotent)
registerBuiltInRenderers();

interface ToolDiscoveryInfo {
  staticTools?: string[];
  dynamicToolsLoaded?: string[];
  autoDiscoveredTools?: Array<{
    toolId: string;
    name: string;
    packageName: string;
    description: string;
  }>;
}

interface Message {
  id: string;
  role: 'USER' | 'ASSISTANT' | 'TOOL';
  content: string;
  toolCalls?: Array<{
    toolCallId: string;
    toolName: string;
    args?: unknown;
    output?: unknown;
  }>;
  inputTokens?: number;
  outputTokens?: number;
  createdAt: string;
  // Tool discovery info (populated from SSE events, per message)
  toolDiscovery?: ToolDiscoveryInfo;
}

interface ToolCall {
  toolCallId: string;
  toolName: string;
  input?: unknown;
  output?: unknown;
  status: 'pending' | 'running' | 'success' | 'error';
  isError?: boolean;
}

interface EnvVarWarning {
  toolId: string;
  toolName: string;
  packageName: string;
  envVar: {
    name: string;
    description: string;
    required: boolean;
  };
}

interface Conversation {
  id: string;
  title: string | null;
  executionState: string;
  inputTokensTotal: number;
  outputTokensTotal: number;
  createdAt: string;
  updatedAt: string;
}

/**
 * Convert ToolCall status to ToolState
 */
function statusToToolState(status: ToolCall['status']): ToolState {
  switch (status) {
    case 'pending':
      return 'partial-call';
    case 'running':
      return 'call';
    case 'success':
    case 'error':
      return 'result';
  }
}

/**
 * Convert ToolCall to ToolPart for rendering
 */
function toolCallToToolPart(tc: ToolCall): ToolPart {
  return {
    type: tc.status === 'success' || tc.status === 'error' ? 'tool-result' : 'tool-call',
    toolCallId: tc.toolCallId,
    toolName: tc.toolName,
    args: tc.input,
    result: tc.isError ? { error: tc.output } : tc.output,
    state: statusToToolState(tc.status),
  };
}

/**
 * Omega Chat Page
 */
// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex chat page with multiple UI states and SSE handling
export default function OmegaChatPage(): React.ReactElement {
  const params = useParams();
  const router = useRouter();
  const conversationId = params.conversationId as string;

  const [conversation, setConversation] = useState<Conversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSending, setIsSending] = useState(false);
  const [streamingContent, setStreamingContent] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [toolCalls, setToolCalls] = useState<ToolCall[]>([]);
  const [viewMode, setViewMode] = useState<'chat' | 'debug'>('chat');
  // Map of message IDs to their tool discovery info (persisted in frontend state)
  const [messageToolDiscovery, setMessageToolDiscovery] = useState<Map<string, ToolDiscoveryInfo>>(
    new Map()
  );
  // Environment variable warnings for tools that need API keys
  const [envWarnings, setEnvWarnings] = useState<EnvVarWarning[]>([]);
  // Status message from SSE status events
  const [statusMessage, setStatusMessage] = useState<string | null>(null);

  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  // AbortController for stop button
  const abortControllerRef = useRef<AbortController | null>(null);
  // Smart auto-scroll: only scroll when user is near bottom
  const isNearBottomRef = useRef(true);

  // Fetch conversation details
  const fetchConversation = useCallback(async () => {
    try {
      const response = await fetch(`/api/omega/conversations/${conversationId}`);

      if (response.status === 404) {
        setError('Conversation not found');
        setIsLoading(false);
        return;
      }

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || 'Failed to fetch conversation');
      }

      const data = await response.json();
      // API returns conversation data directly with messages nested
      const { messages: messageList, ...conversationData } = data.data;
      setConversation(conversationData);
      setMessages(messageList || []);
    } catch (err) {
      console.error('Failed to fetch conversation:', err);
      setError(err instanceof Error ? err.message : 'Failed to fetch conversation');
    } finally {
      setIsLoading(false);
    }
  }, [conversationId]);

  useEffect(() => {
    fetchConversation();
  }, [fetchConversation]);

  // Smart auto-scroll: only scroll when user is near the bottom
  const handleScroll = useCallback(() => {
    const el = messagesContainerRef.current;
    if (!el) return;
    isNearBottomRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < 100;
  }, []);

  // biome-ignore lint/correctness/useExhaustiveDependencies: We intentionally trigger scroll when messages/streamingContent change
  useEffect(() => {
    if (isNearBottomRef.current && messagesContainerRef.current) {
      messagesContainerRef.current.scrollTop = messagesContainerRef.current.scrollHeight;
    }
  }, [messages, streamingContent]);

  // Check for initial prompt from landing page
  // biome-ignore lint/correctness/useExhaustiveDependencies: Only run on mount and when messages load
  useEffect(() => {
    const initialPrompt = sessionStorage.getItem(`omega_prompt_${conversationId}`);
    if (initialPrompt && messages.length === 0 && !isSending) {
      sessionStorage.removeItem(`omega_prompt_${conversationId}`);
      setInput(initialPrompt);
      // Auto-send after a brief delay
      const timer = setTimeout(() => {
        handleSendWithContent(initialPrompt);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [conversationId, messages.length]);

  // Stop button handler
  const handleStop = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
    }
    setIsSending(false);
    setStatusMessage(null);
    // Keep partial streaming content as a message
    setStreamingContent((prev) => {
      if (prev) {
        const partialMessage: Message = {
          id: `partial-${Date.now()}`,
          role: 'ASSISTANT',
          content: prev,
          createdAt: new Date().toISOString(),
        };
        setMessages((msgs) => [...msgs, partialMessage]);
      }
      return '';
    });
    setToolCalls([]);
    inputRef.current?.focus();
  }, []);

  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Chat send handler with streaming and tool calls
  const handleSendWithContent = async (messageContent: string) => {
    if (!messageContent.trim() || isSending) return;

    setInput('');
    setIsSending(true);
    setStreamingContent('');
    setError(null);
    setToolCalls([]);
    setStatusMessage(null);

    // Create AbortController for this request
    const controller = new AbortController();
    abortControllerRef.current = controller;

    // Optimistically add user message
    const userMessage: Message = {
      id: `temp-${Date.now()}`,
      role: 'USER',
      content: messageContent,
      createdAt: new Date().toISOString(),
    };
    setMessages((prev) => [...prev, userMessage]);

    // Track accumulated data for constructing final message
    let accumulatedContent = '';
    let completedToolCalls: ToolCall[] = [];

    try {
      const response = await fetch(`/api/omega/conversations/${conversationId}/messages`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: messageContent }),
        signal: controller.signal,
      });

      if (!response.ok) {
        // Handle non-JSON error responses gracefully
        let errorMessage = 'Failed to send message';
        try {
          const errorData = await response.json();
          errorMessage = errorData.error || errorMessage;
        } catch {
          // Response body isn't valid JSON - use status text
          errorMessage = `Server error: ${response.status} ${response.statusText}`;
        }
        throw new Error(errorMessage);
      }

      // Handle SSE stream
      const reader = response.body?.getReader();
      if (!reader) throw new Error('No response body');

      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        // Parse SSE events
        const lines = buffer.split('\n');
        buffer = lines.pop() || ''; // Keep incomplete line in buffer

        let eventType = '';
        for (const line of lines) {
          if (line.startsWith('event: ')) {
            eventType = line.slice(7);
          } else if (line.startsWith('data: ')) {
            // SSE parse safety: wrap JSON.parse in try/catch
            let data: unknown;
            try {
              data = JSON.parse(line.slice(6));
            } catch {
              console.warn('Failed to parse SSE data:', line.slice(6));
              continue;
            }

            const d = data as Record<string, unknown>;

            switch (eventType) {
              case 'status':
                // Display status messages from the server
                if (d.message && typeof d.message === 'string') {
                  setStatusMessage(d.message);
                }
                break;
              case 'env.warning':
                // Set environment variable warnings
                if (d.missingEnvVars && Array.isArray(d.missingEnvVars)) {
                  setEnvWarnings(d.missingEnvVars as EnvVarWarning[]);
                }
                break;
              case 'message.delta':
                setStatusMessage(null);
                accumulatedContent += (d as { content: string }).content;
                setStreamingContent((prev) => prev + (d as { content: string }).content);
                break;
              case 'run.step.tool.started':
                setStatusMessage(null);
                // Add tool call to tracking
                setToolCalls((prev) => {
                  const updated = [
                    ...prev,
                    {
                      toolCallId: d.toolCallId as string,
                      toolName: d.toolName as string,
                      input: d.input,
                      status: 'running' as const,
                    },
                  ];
                  completedToolCalls = updated;
                  return updated;
                });
                break;
              case 'run.step.tool.completed':
                // Update tool call with result
                setToolCalls((prev) => {
                  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Tool call update logic
                  const updated = prev.map((tc) =>
                    tc.toolCallId === d.toolCallId
                      ? {
                          ...tc,
                          output: d.output,
                          status: d.isError ? ('error' as const) : ('success' as const),
                          isError: d.isError as boolean | undefined,
                        }
                      : tc
                  );
                  completedToolCalls = updated;
                  return updated;
                });
                break;
              case 'run.completed': {
                // Build the assistant message from accumulated SSE data
                const assistantMessage: Message = {
                  id: (d.messageId as string) || `msg-${Date.now()}`,
                  role: 'ASSISTANT',
                  content: accumulatedContent,
                  toolCalls: completedToolCalls
                    .filter((tc) => tc.status === 'success' || tc.status === 'error')
                    .map((tc) => ({
                      toolCallId: tc.toolCallId,
                      toolName: tc.toolName,
                      args: tc.input,
                      output: tc.output,
                    })),
                  inputTokens: d.inputTokens as number,
                  outputTokens: d.outputTokens as number,
                  createdAt: new Date().toISOString(),
                };

                // Build tool results message if there were tool calls
                const toolResultEntries = completedToolCalls
                  .filter((tc) => tc.output !== undefined)
                  .map((tc) => ({
                    toolCallId: tc.toolCallId,
                    toolName: tc.toolName,
                    output: tc.output,
                  }));

                setMessages((prev) => {
                  const updated = [...prev, assistantMessage];
                  if (toolResultEntries.length > 0) {
                    updated.push({
                      id: `tool-${Date.now()}`,
                      role: 'TOOL',
                      content: 'Tool results',
                      toolCalls: toolResultEntries,
                      createdAt: new Date().toISOString(),
                    });
                  }
                  return updated;
                });

                // Update conversation token totals locally
                if (conversation) {
                  setConversation({
                    ...conversation,
                    inputTokensTotal:
                      conversation.inputTokensTotal + ((d.inputTokens as number) || 0),
                    outputTokensTotal:
                      conversation.outputTokensTotal + ((d.outputTokens as number) || 0),
                    executionState: 'idle',
                  });
                }

                // Associate tool discovery info
                const toolDiscovery: ToolDiscoveryInfo = {
                  staticTools: d.staticTools as string[],
                  dynamicToolsLoaded: d.dynamicToolsLoaded as string[],
                  autoDiscoveredTools:
                    d.autoDiscoveredTools as ToolDiscoveryInfo['autoDiscoveredTools'],
                };
                setMessageToolDiscovery((prev) => {
                  const next = new Map(prev);
                  next.set(assistantMessage.id, toolDiscovery);
                  return next;
                });

                setStreamingContent('');
                setToolCalls([]);
                setStatusMessage(null);
                break;
              }
              case 'run.failed':
                throw new Error(d.error as string);
            }
          }
        }
      }
    } catch (err) {
      // Handle AbortError gracefully (user clicked stop)
      if (err instanceof DOMException && err.name === 'AbortError') {
        // Already handled in handleStop
        return;
      }
      console.error('Failed to send message:', err);
      setError(err instanceof Error ? err.message : 'Failed to send message');
      // Remove optimistic message on error
      setMessages((prev) => prev.filter((m) => m.id !== userMessage.id));
    } finally {
      abortControllerRef.current = null;
      setIsSending(false);
      setStreamingContent('');
      setStatusMessage(null);
      inputRef.current?.focus();
    }
  };

  const handleSend = async () => {
    if (!input.trim() || isSending) return;
    await handleSendWithContent(input.trim());
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const startNewConversation = async () => {
    try {
      const response = await fetch('/api/omega/conversations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || 'Failed to create conversation');
      }

      const data = await response.json();
      router.push(`/omega/${data.data.id}`);
    } catch (err) {
      console.error('Failed to create conversation:', err);
      setError(err instanceof Error ? err.message : 'Failed to create conversation');
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <div className="flex items-center justify-center h-[calc(100vh-64px)]">
          <Icon icon="loader" size="lg" className="animate-spin text-foreground-secondary" />
        </div>
      </div>
    );
  }

  if (error && !conversation) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <div className="flex items-center justify-center h-[calc(100vh-64px)]">
          <div className="text-center">
            <Icon icon="alertCircle" size="lg" className="mx-auto text-error mb-4" />
            <h2 className="text-lg font-medium text-foreground mb-2">Unable to Load Chat</h2>
            <p className="text-foreground-secondary mb-4">{error}</p>
            <Link href="/omega">
              <Button>Start New Conversation</Button>
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <AppHeader />

      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Chat Header */}
        <div className="border-b border-border bg-surface/50 px-4 py-3">
          <div className="flex items-center justify-between max-w-4xl mx-auto">
            <div className="flex items-center gap-3">
              <Link
                href="/omega"
                className="p-2 rounded-lg hover:bg-surface-secondary transition-colors"
              >
                <Icon icon="arrowLeft" size="sm" className="text-foreground-secondary" />
              </Link>
              <div>
                <h1 className="text-lg font-semibold text-foreground">
                  {conversation?.title || 'New Conversation'}
                </h1>
                <div className="flex items-center gap-2 text-sm text-foreground-tertiary">
                  <Badge variant="secondary" size="sm">
                    Omega
                  </Badge>
                  <span>GPT-4.1 Mini</span>
                  {conversation && (
                    <span className="text-xs">
                      {conversation.inputTokensTotal + conversation.outputTokensTotal} tokens
                    </span>
                  )}
                </div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <Link href="/omega/settings">
                <Button variant="ghost" size="sm">
                  <Icon icon="key" size="xs" className="mr-2" />
                  Settings
                </Button>
              </Link>
              <Button variant="ghost" size="sm" onClick={startNewConversation}>
                <Icon icon="plus" size="xs" className="mr-2" />
                New Chat
              </Button>
            </div>
          </div>
          {/* View Mode Tabs */}
          <div className="flex gap-1 mt-3 max-w-4xl mx-auto">
            <Button
              variant={viewMode === 'chat' ? 'default' : 'ghost'}
              size="sm"
              onClick={() => setViewMode('chat')}
            >
              Chat
            </Button>
            <Button
              variant={viewMode === 'debug' ? 'default' : 'ghost'}
              size="sm"
              onClick={() => setViewMode('debug')}
            >
              Debug JSON
            </Button>
          </div>
        </div>

        {/* Debug JSON View */}
        {viewMode === 'debug' && (
          <div className="flex-1 overflow-auto p-4 bg-background">
            <div className="max-w-4xl mx-auto space-y-6">
              {/* Header with Copy Button */}
              <div className="flex items-start justify-between">
                <div>
                  <h2 className="text-sm font-medium text-foreground mb-2">
                    Messages with Tool Discovery ({messages.length} messages)
                  </h2>
                  <p className="text-xs text-foreground-tertiary">
                    Each message shows the tools discovered and loaded during that response.
                  </p>
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    // Merge tool discovery info into messages for export
                    const messagesWithTools = messages.map((m) => ({
                      ...m,
                      toolDiscovery: messageToolDiscovery.get(m.id) || null,
                    }));
                    navigator.clipboard.writeText(JSON.stringify(messagesWithTools, null, 2));
                  }}
                >
                  <Icon icon="copy" size="xs" className="mr-2" />
                  Copy All JSON
                </Button>
              </div>

              {/* Per-Message View */}
              {/* biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Debug view with multiple conditional sections */}
              {messages.map((message, index) => {
                const discovery = messageToolDiscovery.get(message.id);
                return (
                  <div
                    key={message.id}
                    className="bg-surface-secondary border border-border rounded-lg overflow-hidden"
                  >
                    {/* Message Header */}
                    <div className="px-4 py-3 border-b border-border/50 bg-surface/50">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          <span className="text-xs text-foreground-tertiary">#{index + 1}</span>
                          <Badge
                            variant={
                              message.role === 'USER'
                                ? 'secondary'
                                : message.role === 'ASSISTANT'
                                  ? 'default'
                                  : 'outline'
                            }
                            size="sm"
                          >
                            {message.role}
                          </Badge>
                          <span className="text-xs text-foreground-tertiary font-mono">
                            {message.id.slice(0, 8)}...
                          </span>
                        </div>
                        <span className="text-xs text-foreground-tertiary">
                          {new Date(message.createdAt).toLocaleTimeString()}
                        </span>
                      </div>
                    </div>

                    {/* Message Content */}
                    <div className="p-4 space-y-4">
                      {/* Content */}
                      <div>
                        <div className="text-[10px] uppercase tracking-wider text-foreground-tertiary mb-2">
                          Content
                        </div>
                        <pre className="text-xs font-mono bg-background/50 rounded p-3 overflow-x-auto whitespace-pre-wrap max-h-48 overflow-y-auto">
                          {message.content || '(empty)'}
                        </pre>
                      </div>

                      {/* Tool Discovery (only for assistant messages) */}
                      {message.role === 'ASSISTANT' && discovery && (
                        <div className="space-y-3 pt-3 border-t border-border/50">
                          <div className="text-[10px] uppercase tracking-wider text-foreground-tertiary">
                            Tool Discovery for this Response
                          </div>

                          {/* Static Tools */}
                          {discovery.staticTools && discovery.staticTools.length > 0 && (
                            <div>
                              <div className="text-xs text-foreground-secondary mb-1">
                                Static Tools ({discovery.staticTools.length})
                              </div>
                              <div className="flex flex-wrap gap-1">
                                {discovery.staticTools.map((name) => (
                                  <span
                                    key={name}
                                    className="px-2 py-0.5 bg-blue-500/10 text-blue-500 text-[10px] font-mono rounded"
                                  >
                                    {name}
                                  </span>
                                ))}
                              </div>
                            </div>
                          )}

                          {/* Auto-Discovered Tools */}
                          {discovery.autoDiscoveredTools &&
                            discovery.autoDiscoveredTools.length > 0 && (
                              <div>
                                <div className="text-xs text-foreground-secondary mb-1">
                                  Auto-Discovered via BM25 ({discovery.autoDiscoveredTools.length})
                                </div>
                                <div className="space-y-1">
                                  {discovery.autoDiscoveredTools.map((t) => (
                                    <div
                                      key={t.toolId}
                                      className="text-[10px] font-mono bg-background/50 rounded px-2 py-1"
                                    >
                                      <span className="text-primary">{t.packageName}</span>
                                      <span className="text-foreground-tertiary">::</span>
                                      <span className="text-foreground">{t.name}</span>
                                      <span className="text-foreground-tertiary ml-2">
                                        - {t.description?.slice(0, 60)}
                                        {(t.description?.length || 0) > 60 ? '...' : ''}
                                      </span>
                                    </div>
                                  ))}
                                </div>
                              </div>
                            )}

                          {/* Dynamically Loaded Tools */}
                          {discovery.dynamicToolsLoaded &&
                            discovery.dynamicToolsLoaded.length > 0 && (
                              <div>
                                <div className="text-xs text-foreground-secondary mb-1">
                                  Dynamic Tools Loaded ({discovery.dynamicToolsLoaded.length})
                                </div>
                                <div className="flex flex-wrap gap-1">
                                  {discovery.dynamicToolsLoaded.map((name) => (
                                    <span
                                      key={name}
                                      className="px-2 py-0.5 bg-primary/10 text-primary text-[10px] font-mono rounded"
                                    >
                                      {name}
                                    </span>
                                  ))}
                                </div>
                              </div>
                            )}
                        </div>
                      )}

                      {/* Tool Calls */}
                      {message.toolCalls && message.toolCalls.length > 0 && (
                        <div className="pt-3 border-t border-border/50">
                          <div className="text-[10px] uppercase tracking-wider text-foreground-tertiary mb-2">
                            Tool Calls ({message.toolCalls.length})
                          </div>
                          <pre className="text-xs font-mono bg-background/50 rounded p-3 overflow-x-auto whitespace-pre-wrap max-h-48 overflow-y-auto">
                            {JSON.stringify(message.toolCalls, null, 2)}
                          </pre>
                        </div>
                      )}

                      {/* Token Usage */}
                      {(message.inputTokens || message.outputTokens) && (
                        <div className="text-[10px] text-foreground-tertiary font-mono pt-2 border-t border-border/50">
                          {message.inputTokens && <span>Input: {message.inputTokens}</span>}
                          {message.inputTokens && message.outputTokens && <span> | </span>}
                          {message.outputTokens && <span>Output: {message.outputTokens}</span>}
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}

              {/* Empty state */}
              {messages.length === 0 && (
                <div className="text-center py-8 text-foreground-tertiary">
                  No messages yet. Start a conversation to see debug data.
                </div>
              )}
            </div>
          </div>
        )}

        {/* Chat View */}
        {viewMode === 'chat' && (
          <>
            {/* Messages */}
            <div className="flex-1 overflow-hidden">
              {messages.length === 0 && !streamingContent ? (
                <div className="h-full flex items-center justify-center p-4">
                  <div className="text-center">
                    <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center mx-auto mb-4">
                      <Icon icon="star" size="lg" className="text-primary" />
                    </div>
                    <h3 className="text-lg font-medium text-foreground mb-2">
                      Start a conversation with Omega
                    </h3>
                    <p className="text-foreground-secondary max-w-sm">
                      Describe what you need, and Omega will find and use the right tools from the
                      TPMJS registry.
                    </p>
                  </div>
                </div>
              ) : (
                <div
                  ref={messagesContainerRef}
                  className="h-full overflow-y-auto"
                  onScroll={handleScroll}
                >
                  <div className="max-w-4xl mx-auto">
                    {/* Messages */}
                    {messages.map((message) => (
                      <div key={message.id} className="px-4 py-2">
                        {/* USER message */}
                        {message.role === 'USER' && (
                          <div className="flex justify-end">
                            <div className="max-w-[80%] rounded-lg p-4 bg-primary text-primary-foreground">
                              <div className="text-sm whitespace-pre-wrap">{message.content}</div>
                            </div>
                          </div>
                        )}

                        {/* ASSISTANT message */}
                        {message.role === 'ASSISTANT' && message.content && (
                          <div className="flex justify-start">
                            <div className="max-w-[80%] rounded-lg p-4 bg-surface-secondary">
                              <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
                                <Streamdown>{message.content}</Streamdown>
                              </div>
                              {/* Token usage for debugging */}
                              {(message.inputTokens || message.outputTokens) && (
                                <div className="mt-2 pt-2 border-t border-border/50 text-[10px] text-foreground-tertiary font-mono">
                                  {message.inputTokens && <span>In: {message.inputTokens}</span>}
                                  {message.inputTokens && message.outputTokens && <span> | </span>}
                                  {message.outputTokens && <span>Out: {message.outputTokens}</span>}
                                </div>
                              )}
                            </div>
                          </div>
                        )}

                        {/* TOOL message - show tool results from toolCalls field */}
                        {message.role === 'TOOL' && message.toolCalls && (
                          <div className="flex justify-start">
                            <div className="max-w-[80%] space-y-2">
                              {message.toolCalls.map((tc) => (
                                <ToolRenderer
                                  key={tc.toolCallId}
                                  part={{
                                    type: 'tool-result',
                                    toolCallId: tc.toolCallId,
                                    toolName: tc.toolName,
                                    args: tc.args,
                                    result: tc.output,
                                    state: 'result',
                                  }}
                                  isStreaming={false}
                                />
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    ))}

                    {/* Live tool calls during streaming */}
                    {toolCalls.length > 0 && (
                      <div className="px-4 pb-4 space-y-2">
                        {toolCalls.map((tc) => (
                          <div key={tc.toolCallId} className="flex justify-start">
                            <div className="max-w-[80%]">
                              <ToolRenderer
                                part={toolCallToToolPart(tc)}
                                isStreaming={tc.status === 'running'}
                              />
                            </div>
                          </div>
                        ))}
                      </div>
                    )}

                    {/* Streaming content */}
                    {streamingContent && (
                      <div className="px-4 pb-4">
                        <div className="flex justify-start">
                          <div className="max-w-[80%] rounded-lg p-4 bg-surface-secondary">
                            <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
                              <Streamdown>{streamingContent}</Streamdown>
                            </div>
                            <span className="inline-block w-2 h-4 bg-primary animate-pulse ml-1" />
                          </div>
                        </div>
                      </div>
                    )}

                    {/* Thinking indicator with status message */}
                    {isSending && !streamingContent && toolCalls.length === 0 && (
                      <div className="px-4 pb-4">
                        <div className="flex justify-start">
                          <div className="rounded-lg p-4 bg-surface-secondary">
                            <div className="flex items-center gap-2 text-foreground-secondary">
                              <Icon icon="loader" size="sm" className="animate-spin" />
                              <span className="text-sm">
                                {statusMessage || 'Omega is thinking...'}
                              </span>
                            </div>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* Environment Variable Warnings */}
            {envWarnings.length > 0 && (
              <div className="max-w-4xl mx-auto">
                <EnvVarWarningBanner warnings={envWarnings} onDismiss={() => setEnvWarnings([])} />
              </div>
            )}

            {/* Error Message */}
            {error && (
              <div className="px-4 py-2 bg-error/10 border-t border-error/20">
                <p className="text-sm text-error max-w-4xl mx-auto">{error}</p>
              </div>
            )}

            {/* Input Area */}
            <div className="border-t border-border p-4">
              <div className="flex items-end gap-2 max-w-4xl mx-auto">
                <Textarea
                  ref={inputRef}
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={handleKeyDown}
                  placeholder="Ask Omega anything..."
                  rows={1}
                  resize="none"
                  className="flex-1 min-h-[48px] max-h-[200px]"
                  style={{
                    height: 'auto',
                    minHeight: '48px',
                  }}
                  onInput={(e) => {
                    const target = e.target as HTMLTextAreaElement;
                    target.style.height = 'auto';
                    target.style.height = `${Math.min(target.scrollHeight, 200)}px`;
                  }}
                />
                {isSending ? (
                  <Button onClick={handleStop} variant="destructive">
                    <Icon icon="x" size="sm" />
                  </Button>
                ) : (
                  <Button onClick={handleSend} disabled={!input.trim()}>
                    <Icon icon="send" size="sm" />
                  </Button>
                )}
              </div>
              <p className="text-xs text-foreground-tertiary mt-2 max-w-4xl mx-auto">
                Press Enter to send, Shift+Enter for new line
              </p>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

